#!/usr/bin/env python3
"""Game-type catalog for the dev kit wizard, built from every title in the ROM catalog.
Each type: what it is, which catalogued games it learns from, the systems those games use (from the catalog's
systems table where we measured them), suggested controls, bottom-screen layout, music style, art style, and which
engine builds it today."""
import json, sqlite3, sys
db = sqlite3.connect('/home/claude/out/rom_catalog.sqlite')
games = [r[0] for r in db.execute('select game from games')]
systems = db.execute('select system, game from systems').fetchall()
def titles(*keys): return sorted({g for g in games if any(k.lower() in g.lower() for k in keys)})
def sysfor(*keys): return sorted({s for s, g in systems if any(k.lower() in g.lower() for k in keys)})
READY = 'side2d'
G = []
def add(id, name, family, about, keys, engine, layout, music, art, controls, consoles, extra=None):
    e = dict(id=id, name=name, family=family, about=about, learns_from=titles(*keys), systems=sysfor(*keys), engine=engine,
             status='ready' if engine == READY else 'blueprint', touch_layout=layout, music=music, art=art, controls=controls, consoles=consoles)
    if extra: e.update(extra)
    G.append(e)
P = ['ds', 'snes', 'psx']
