json.dump({'source': 'NOTAREAL ROM catalog (%d titles); systems from measured catalog facts' % len(games), 'types': G, 'splitter': {'about': 'Game type splitter: combine two types in one game. Each level/area picks which type it plays as (e.g. platformer stages + top-down overworld, or an RPG with racing missions). The project keeps one cast, one art style and one soundtrack across both.', 'pairs_ready': [['platformer', 'runner'], ['platformer', 'kids_first'], ['platformer', 'puzzle_platformer'], ['collectathon2d', 'runner']]}}, open('/home/claude/notareal-kit/ds/presets/genres.json', 'w'), indent=1)
covered = {t for g in G for t in g['learns_from']}
print(len(G), 'types;', sum(g['status'] == 'ready' for g in G), 'ready;', 'titles covered', len(covered), 'of', len(games))
print('not covered:', sorted(set(games) - covered))
